insert into public.qse_catalog_decks(id,name,creator,description,visibility,metadata,published_at,updated_at) values('diva_pop','Diva Pop','Quem Sou Eu','O universo da música ganha vida em dez retratos de animação 3D, entre estrelas solo, grupos cheios de carisma, brilhos de palco e visuais inesquecíveis. Diva Pop reúne personalidades originais que brincam com as tendências e a estética da cultura pop mundial: há glamour retrô, atitude urbana, energia jovem e figurinos futuristas. Observe os cabelos, roupas, acessórios e poses de cada carta e descubra se você reconhece quem está no centro do espetáculo.','public','{"tags":["pop","música","artistas"],"category":"Música pop","official":true,"original_language":"pt-BR","card_labels_verified":true}'::jsonb,now(),now()) on conflict(id) do update set name=excluded.name,creator=excluded.creator,description=excluded.description,visibility='public',metadata=excluded.metadata,updated_at=now();
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_01','diva_pop','Selina Chartpenter','assets/duel/decks/oficial/diva_pop/carta_01.png','{"description":"À beira de uma estrada ensolarada no deserto, uma estrela de cachos loiros, bandana vermelha de bolinhas e camisa branca aguarda a próxima aventura com sua mala vintage. O short jeans, os saltos vermelhos e o sinal de carona dão personalidade a uma cena retrô, divertida e cheia de confiança.","identification_verified":true}'::jsonb,0) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_02','diva_pop','Millie Eyelash','assets/duel/decks/oficial/diva_pop/carta_02.png','{"description":"Boné preto virado para trás, óculos de armação grossa e olhos verdes expressivos: esta artista prefere o estilo despojado à pose tradicional de diva. Recostada numa cadeira de escritório, mistura camiseta larga, short verde, meias esportivas e sandálias pretas com uma atitude tranquila e irreverente.","identification_verified":true}'::jsonb,1) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_03','diva_pop','Luna Loopa','assets/duel/decks/oficial/diva_pop/carta_03.png','{"description":"Cabelos pretos curtos e desalinhados emolduram o rosto de uma estrela que encara a câmera sob luzes roxas. O casaco de paetês, as argolas prateadas e os colares sobrepostos dão brilho a uma imagem de palco marcada por elegância urbana, confiança e uma personalidade forte.","identification_verified":true}'::jsonb,2) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_04','diva_pop','Livvy Rockdrigo','assets/duel/decks/oficial/diva_pop/carta_04.png','{"description":"Uma jovem de cabelos castanhos ondulados aparece piscando um olho, mostrando a língua e fazendo sinais com as mãos. Adesivos coloridos de flores, estrelas e borboletas, acessórios prateados e um top rosa criam uma estética pop alegre, divertida e um pouco rebelde, perfeita para uma foto cheia de energia.","identification_verified":true}'::jsonb,3) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_05','diva_pop','BLUSHPUNK','assets/duel/decks/oficial/diva_pop/carta_05.png','{"description":"Quatro integrantes se reúnem para uma fotografia carismática, combinando cabelos lilases, castanhos e pretos, tiaras divertidas e laços coloridos. As expressões, os gestos de paz e os acessórios de sapinho e orelhinhas revelam a personalidade de cada uma, enquanto o conjunto transmite amizade e atitude pop.","identification_verified":true}'::jsonb,4) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_06','diva_pop','BEAT7','assets/duel/decks/oficial/diva_pop/carta_06.png','{"description":"Sete jovens músicos posam juntos em um cenário aconchegante, usando cardigãs, jaquetas e suéteres em cores suaves. Os cabelos escuros, os sorrisos e os gestos afetuosos fazem cada integrante se destacar. A composição celebra a sintonia de um grupo cuja energia parece atravessar a fotografia.","identification_verified":true}'::jsonb,5) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_07','diva_pop','Mr. Weekday','assets/duel/decks/oficial/diva_pop/carta_07.png','{"description":"De terno vermelho vibrante, camisa e gravata pretas, óculos escuros e cabelo volumoso, este astro domina a noite com um sorriso radiante. As luzes douradas refletidas nas lentes criam uma atmosfera de show sofisticado, marcada por glamour, mistério e muita presença de palco.","identification_verified":true}'::jsonb,6) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_08','diva_pop','Benny Starz','assets/duel/decks/oficial/diva_pop/carta_08.png','{"description":"Uma faixa vermelha prende os cabelos cacheados de um cantor que veste um terno verde bordado com flores, colete combinando e camisa de gola aberta. Correntes douradas, calça de corte amplo e sapatos claros reforçam o charme retrô. Sua pose tranquila revela uma estrela cheia de ritmo e estilo.","identification_verified":true}'::jsonb,7) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_09','diva_pop','Ariella Big','assets/duel/decks/oficial/diva_pop/carta_09.png','{"description":"Longos cabelos castanhos, tiara preta e brincos verdes em formato de flor acompanham uma roupa verde-lima com top de mangas compridas e saia curta. O sorriso confiante e a maquiagem delicada completam um visual que mistura doçura, elegância contemporânea e personalidade pop.","identification_verified":true}'::jsonb,8) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
insert into public.qse_catalog_cards(id,deck_id,name,image_path,metadata,sort_order) values('diva_pop/carta_10','diva_pop','Lola Glow','assets/duel/decks/oficial/diva_pop/carta_10.png','{"description":"Com franja loiro-platinada reta, maquiagem marcante e figurino de paetês escuros, esta estrela encara a câmera sob luzes azuis. Uma luva metálica prateada emoldura um dos olhos, dando ao retrato uma estética futurista e ousada. Cada detalhe parece preparado para um grande espetáculo.","identification_verified":true}'::jsonb,9) on conflict(id) do update set name=excluded.name,image_path=excluded.image_path,metadata=excluded.metadata,sort_order=excluded.sort_order;
